//--------------->pay with wallet <------------------------
export const payWithWallet = async (
  HashData,
  isError,
  ceilDetail,
  amount,
  setBLoading
) => {
  try {
    setBLoading(true);
    if (!isError) {
      const nftDetail = {
        snapshot: ceilDetail.snapshot,
        user: ceilDetail.user,
        lang: ceilDetail.lang,
        long: ceilDetail.long,
        tilePrice: ceilDetail.tilePrice,
        areaLength: ceilDetail.totalceil.length,
        totalceil: JSON.stringify(ceilDetail.totalceil),
        address: ceilDetail.address,
        token: HashData.hash,
        nftAmount: amount,
        type: "wallet",
      };
      const { data } = await axios.post(`${URL}/buyCellbyWallet`, nftDetail);
      if (data.status === "ok") {
        toast.success(
          `Please wait for transaction confirmation. you can check NFT from your profile!`
        );
        setTimeout(() => {
          window.location.reload();
        }, 5000);

        setBLoading(false);
      } else {
        toast.error("Nft Transfer Failed!");
      }
    }
  } catch (err) {
    // toast.error(err.message)
    console.log(err.message, "err--->");
    setBLoading(false);
  }
};

//--------------->pay with Admin <------------------------
export const payWithAdmin = async (
  HashData,
  isError,
  ceilDetail,
  amount,
  setBLoading,
  specifcAddress
) => {
  try {
    setBLoading(true);
    if (!isError) {
      const nftDetail = {
        snapshot: ceilDetail.snapshot,
        user: ceilDetail.user,
        lang: ceilDetail.lang,
        long: ceilDetail.long,
        tilePrice: ceilDetail.tilePrice,
        areaLength: ceilDetail.totalceil.length,
        totalceil: JSON.stringify(ceilDetail.totalceil),
        address: specifcAddress,
        token: HashData?.hash,
        nftAmount: amount,
        type: "admin",
      };
      const { data } = await axios.post(`${URL}/mintNftByAdmin`, nftDetail);
      if (data) {
        toast.success(
          `Please wait for transaction confirmation. you can check NFT from your profile!`
        );
        setTimeout(() => {
          window.location.reload();
        }, 2000);
      }
      setBLoading(false);
    }
  } catch (err) {
    // toast.error(err.message)
    console.log(err.message, "err--->");
    setBLoading(false);
  }
};

